# Q(cat, level, question, correct, [wrong x3], explanation, source)
from common import Q
Q("quran",1,"How many surahs are there in the Quran?","114",["110","112","120"],"The Mushaf contains 114 surahs, from Al-Fatihah to An-Nas.","The Mushaf (Uthmani order)")
Q("quran",1,"Which surah opens the Quran?","Al-Fatihah",["Al-Baqarah","Al-Ikhlas","An-Nas"],"Al-Fatihah, 'The Opening', is the first surah and is recited in every rak'ah of salah.","Quran 1:1–7")
Q("quran",1,"Which is the longest surah of the Quran?","Al-Baqarah",["Al-Imran","An-Nisa","Al-Kahf"],"Al-Baqarah has 286 verses, the most of any surah.","Quran 2")
Q("quran",1,"Which is the shortest surah of the Quran?","Al-Kawthar",["Al-Ikhlas","Al-Asr","An-Nasr"],"Al-Kawthar has only three short verses.","Quran 108")
Q("quran",2,"Which surah does not begin with Bismillah?","At-Tawbah",["Al-Anfal","Yasin","Al-Fil"],"At-Tawbah (Bara'ah) is the only surah that does not open with Bismillah.","Quran 9:1")
Q("quran",3,"In which surah does Bismillah appear twice?","An-Naml",["Al-Baqarah","Hud","Maryam"],"Besides its opening, Bismillah appears inside Sulayman's letter to the Queen of Sheba.","Quran 27:30")
Q("quran",1,"What were the first words revealed to the Prophet ﷺ?","\"Iqra\" — Read in the name of your Lord",["Al-hamdu lillah","Qul huwa Allahu ahad","Ya ayyuha al-muddaththir"],"The first revelation was the opening verses of Surah Al-Alaq in the cave of Hira.","Quran 96:1–5; Sahih al-Bukhari 3")
Q("quran",1,"On which night did the Quran begin to be revealed?","Laylat al-Qadr",["The night of Isra","The night of Eid","The 15th of Sha'ban"],"Allah says: 'Indeed, We sent it down on the Night of Decree.'","Quran 97:1")
Q("quran",1,"In which month was the Quran first revealed?","Ramadan",["Rajab","Muharram","Dhul Hijjah"],"'The month of Ramadan in which the Quran was revealed…'","Quran 2:185")
Q("quran",1,"In which surah is Ayat al-Kursi?","Al-Baqarah",["Al-Imran","Al-Kahf","Yasin"],"Ayat al-Kursi is verse 255 of Surah Al-Baqarah.","Quran 2:255")
Q("quran",2,"Which surah did the Prophet ﷺ say is equal to one third of the Quran?","Al-Ikhlas",["Al-Fatihah","Al-Kawthar","Al-Falaq"],"The Prophet ﷺ said Surah Al-Ikhlas equals a third of the Quran.","Sahih al-Bukhari 5013")
Q("quran",2,"Memorising the first ten verses of which surah protects from the Dajjal?","Al-Kahf",["Yasin","Al-Mulk","Ar-Rahman"],"The Prophet ﷺ said whoever memorises the first ten verses of Al-Kahf is protected from the Dajjal.","Sahih Muslim 809")
Q("quran",1,"How many juz (parts) is the Quran divided into?","30",["20","40","114"],"The Quran is divided into 30 equal parts (juz / para) for recitation.","Standard Mushaf division")
Q("quran",1,"Which angel brought the revelation to the Prophet ﷺ?","Jibril",["Mika'il","Israfil","Malik"],"Jibril (Gabriel) brought the Quran down to the heart of the Prophet ﷺ.","Quran 2:97")
Q("quran",1,"Who is the only woman mentioned by name in the Quran?","Maryam",["Khadijah","Hawwa","Asiyah"],"Maryam, mother of Isa (peace be upon them), is named in the Quran and a surah carries her name.","Quran 19:16")
Q("quran",2,"Which prophet is mentioned by name most often in the Quran?","Musa",["Ibrahim","Nuh","Isa"],"Musa (peace be upon him) is named more than any other prophet, over 130 times.","Quran concordance")
Q("quran",1,"Which surah is named after the ant?","An-Naml",["An-Nahl","Al-Ankabut","Al-Fil"],"An-Naml (27) tells how an ant warned the others of Sulayman's army.","Quran 27:18")
Q("quran",2,"In which surah is 'Which of the favours of your Lord will you deny?' repeated?","Ar-Rahman",["Al-Waqi'ah","Al-Mulk","Al-Qamar"],"The verse is repeated 31 times in Surah Ar-Rahman.","Quran 55:13")
Q("quran",2,"Under which caliph was the Quran first gathered into one compiled copy?","Abu Bakr",["Umar","Uthman","Ali"],"After the Battle of Yamamah, Abu Bakr had Zayd ibn Thabit gather the Quran into one compilation.","Sahih al-Bukhari 4986")
Q("quran",2,"Which caliph sent standard copies of the Mushaf to the major cities?","Uthman",["Abu Bakr","Umar","Mu'awiyah"],"Uthman had copies made from Abu Bakr's compilation and sent them to the provinces.","Sahih al-Bukhari 4987")
Q("quran",1,"Which surah is the last in the order of the Mushaf?","An-Nas",["Al-Falaq","Al-Ikhlas","Al-Asr"],"An-Nas (114) closes the Mushaf.","Quran 114")
Q("quran",2,"Which two surahs are known as al-Mu'awwidhatayn?","Al-Falaq and An-Nas",["Al-Ikhlas and Al-Kafirun","Al-Fatihah and Al-Ikhlas","Al-Mulk and As-Sajdah"],"They are the two surahs of seeking refuge; the Prophet ﷺ recited them for protection.","Sahih Muslim 814")
Q("quran",2,"Which story does the Quran call 'the best of stories'?","The story of Yusuf",["The story of Musa","The story of the Cave","The story of Nuh"],"Allah says: 'We relate to you the best of stories' at the opening of Surah Yusuf.","Quran 12:3")
Q("quran",1,"Which surah tells the story of the young men of the cave?","Al-Kahf",["Al-Anbiya","Maryam","Al-Isra"],"Al-Kahf (18) is named after the cave in which the believing youths slept.","Quran 18:9–26")
Q("quran",2,"Which surah is named after iron?","Al-Hadid",["Al-Ma'idah","An-Najm","Al-Fajr"],"Al-Hadid (57) mentions that Allah sent down iron with great strength and benefit.","Quran 57:25")
Q("quran",3,"Which Companion is the only one mentioned by name in the Quran?","Zayd ibn Harithah",["Abu Bakr","Bilal","Ali"],"Zayd is named in Surah Al-Ahzab.","Quran 33:37")
Q("quran",1,"Over roughly how many years was the Quran revealed?","23 years",["10 years","40 years","5 years"],"Revelation began when the Prophet ﷺ was 40 and continued until his passing at 63.","Sahih al-Bukhari 3851")
Q("quran",2,"The Quran calls itself 'Al-Furqan'. What does it mean?","The Criterion (between truth and falsehood)",["The Light","The Reminder","The Wise"],"Al-Furqan distinguishes truth from falsehood; Surah 25 carries this name.","Quran 25:1")
Q("quran",1,"Which surah is recited in every rak'ah of salah?","Al-Fatihah",["Al-Ikhlas","Al-Asr","Al-Kawthar"],"The Prophet ﷺ said there is no prayer for one who does not recite the Opening of the Book.","Sahih al-Bukhari 756")
Q("quran",2,"Which surah of thirty verses intercedes for its reciter?","Al-Mulk",["Yasin","Al-Waqi'ah","As-Sajdah"],"The Prophet ﷺ said a surah of thirty verses (Al-Mulk) intercedes for its companion until he is forgiven.","Sunan at-Tirmidhi 2891; Abu Dawud 1400")
Q("quran",1,"Which surah tells of the army of the elephant?","Al-Fil",["Quraysh","Al-Humazah","Al-Ma'un"],"Al-Fil (105) recalls how Allah destroyed Abrahah's army that came to attack the Kaaba.","Quran 105")
Q("quran",1,"Which prophet was swallowed by a great fish?","Yunus",["Musa","Nuh","Ilyas"],"Yunus called upon Allah from the darkness inside the fish and was saved.","Quran 37:139–148; 21:87")
Q("quran",2,"Surah Al-Masad (Tabbat) was revealed about whom?","Abu Lahab",["Abu Jahl","Abu Sufyan","Walid ibn al-Mughirah"],"It was revealed about Abu Lahab, the Prophet's uncle who opposed him, and his wife.","Quran 111")
Q("quran",3,"How many verses does Surah Al-Baqarah have?","286",["200","176","227"],"Al-Baqarah ends at verse 286 with the dua 'Rabbana la tu'akhidhna…'.","Quran 2:286")

Q("seerah",1,"In which city was the Prophet Muhammad ﷺ born?","Makkah",["Madinah","Ta'if","Jerusalem"],"He ﷺ was born in Makkah, in the clan of Banu Hashim of Quraysh.","Ibn Hisham, as-Sirah an-Nabawiyyah")
Q("seerah",2,"In which year was the Prophet ﷺ born?","The Year of the Elephant (c. 570 CE)",["The year of the Hijrah","The Year of Sorrow","610 CE"],"He ﷺ was born in the year Abrahah attacked Makkah with elephants.","Ibn Hisham; Quran 105")
Q("seerah",1,"What was the name of the Prophet's father?","Abdullah",["Abu Talib","Abd al-Muttalib","Hamzah"],"His father Abdullah ibn Abd al-Muttalib passed away before he ﷺ was born.","Ibn Hisham")
Q("seerah",1,"What was the name of the Prophet's mother?","Aminah bint Wahb",["Halimah","Fatimah bint Asad","Barakah"],"Aminah passed away at al-Abwa when he ﷺ was about six years old.","Ibn Hisham")
Q("seerah",2,"Which grandfather took care of the Prophet ﷺ after his mother passed away?","Abd al-Muttalib",["Hashim","Abd Manaf","Qusayy"],"His grandfather Abd al-Muttalib cared for him until he passed away two years later.","Ibn Hisham")
Q("seerah",1,"Which uncle raised the Prophet ﷺ and protected him?","Abu Talib",["Abu Lahab","Abbas","Hamzah"],"Abu Talib raised him from age eight and protected him in Makkah.","Ibn Hisham")
Q("seerah",2,"What was the name of the Prophet's wet-nurse in the desert?","Halimah as-Sa'diyyah",["Umm Ayman","Thuwaybah","Umm Salamah"],"He ﷺ spent his early childhood with Halimah of Banu Sa'd.","Ibn Hisham")
Q("seerah",1,"Who was the Prophet's first wife?","Khadijah",["Aishah","Sawdah","Hafsah"],"Khadijah bint Khuwaylid, mother of the believers, was his first wife and first to believe.","Sahih al-Bukhari 3")
Q("seerah",1,"In which cave did the first revelation come?","Hira",["Thawr","Uhud","Safa"],"He ﷺ used to worship in the cave of Hira on Jabal an-Nur.","Sahih al-Bukhari 3")
Q("seerah",1,"How old was the Prophet ﷺ when the revelation began?","40",["25","30","53"],"Revelation began at the age of forty.","Sahih al-Bukhari 3851")
Q("seerah",1,"To which city did the Prophet ﷺ migrate?","Madinah (Yathrib)",["Ta'if","Abyssinia","Jerusalem"],"In the Hijrah he ﷺ migrated to Yathrib, which became Madinat an-Nabi.","Quran 9:40; Sahih al-Bukhari 3905")
Q("seerah",1,"Who accompanied the Prophet ﷺ on the Hijrah?","Abu Bakr",["Umar","Ali","Uthman"],"Abu Bakr is 'the second of two' mentioned in the Quran.","Quran 9:40")
Q("seerah",2,"In which cave did the Prophet ﷺ and Abu Bakr hide during the Hijrah?","Thawr",["Hira","Uhud","Kahf"],"They stayed three nights in the cave of Thawr south of Makkah.","Sahih al-Bukhari 3905")
Q("seerah",2,"Which was the first masjid built by the Prophet ﷺ?","Masjid Quba",["Masjid an-Nabawi","Masjid al-Qiblatayn","Masjid al-Haram"],"He ﷺ built Quba on arrival near Madinah; it is 'founded on taqwa'.","Quran 9:108; Ibn Hisham")
Q("seerah",1,"Which was the first major battle in Islam?","Badr",["Uhud","Khandaq","Hunayn"],"The Battle of Badr took place in Ramadan, 2 AH.","Quran 3:123")
Q("seerah",2,"About how many Muslims fought at Badr?","313",["1,000","700","3,000"],"Around 313 Companions faced an army of about a thousand.","Sahih al-Bukhari 3957")
Q("seerah",2,"Whose idea was digging the trench (Khandaq) around Madinah?","Salman al-Farisi",["Abu Bakr","Khalid ibn al-Walid","Sa'd ibn Mu'adh"],"Salman suggested the Persian practice of defending with a trench in 5 AH.","Ibn Hisham; Ibn Sa'd")
Q("seerah",2,"In which year was the Treaty of Hudaybiyyah?","6 AH",["2 AH","8 AH","10 AH"],"The treaty was agreed in Dhul Qa'dah 6 AH; the Quran calls it a clear victory.","Quran 48:1; Sahih al-Bukhari 2731")
Q("seerah",2,"In which year was Makkah conquered?","8 AH",["6 AH","5 AH","10 AH"],"The Conquest of Makkah took place in Ramadan, 8 AH.","Sahih al-Bukhari 4275")
Q("seerah",2,"In which year was the Farewell Hajj?","10 AH",["8 AH","9 AH","11 AH"],"The Prophet ﷺ performed his only Hajj in 10 AH.","Sahih Muslim 1218")
Q("seerah",1,"At what age did the Prophet ﷺ pass away?","63",["60","65","70"],"He ﷺ passed away at sixty-three in Madinah.","Sahih al-Bukhari 3536")
Q("seerah",2,"Where is the Prophet ﷺ buried?","In Aishah's room, now within Masjid an-Nabawi",["Jannat al-Baqi","Mount Uhud","Masjid Quba"],"He ﷺ was buried where he passed away, in the room of Aishah.","Sunan at-Tirmidhi 1018")
Q("seerah",2,"Why is one year called 'the Year of Sorrow'?","Khadijah and Abu Talib passed away",["The Battle of Uhud","The boycott began","The Prophet's son passed away"],"Both his wife Khadijah and his uncle Abu Talib passed away in the same year.","Ibn Hisham")
Q("seerah",1,"What gift was given on the night of Isra and Mi'raj?","The five daily prayers",["Fasting in Ramadan","Zakat","The Hajj"],"The five prayers were made obligatory on the night of the Ascension.","Sahih al-Bukhari 349")
Q("seerah",1,"On the Isra, the Prophet ﷺ was taken from Masjid al-Haram to…","Masjid al-Aqsa",["Masjid an-Nabawi","Masjid Quba","Mount Sinai"],"'Glory be to Him who took His servant by night… to al-Masjid al-Aqsa.'","Quran 17:1")
Q("seerah",1,"What title did the people of Makkah give the Prophet ﷺ before prophethood?","Al-Amin (the Trustworthy)",["Al-Faruq","As-Siddiq","Dhun-Nurayn"],"Quraysh called him al-Sadiq al-Amin for his honesty.","Ibn Hisham")
Q("seerah",1,"Who was the first person to believe in the Prophet ﷺ?","Khadijah",["Abu Bakr","Ali","Zayd"],"Khadijah believed in him from the first revelation; Abu Bakr was the first free man, Ali the first child.","Sahih al-Bukhari 3; Ibn Hisham")
Q("seerah",1,"Who was the first muezzin of Islam?","Bilal ibn Rabah",["Abdullah ibn Umm Maktum","Abu Mahdhurah","Sa'd al-Qaraz"],"The Prophet ﷺ chose Bilal for his beautiful, strong voice.","Sunan Abi Dawud 499")
Q("seerah",2,"Where did the first group of Muslims migrate to escape persecution?","Abyssinia (Habashah)",["Madinah","Ta'if","Yemen"],"They migrated to the just Christian king, an-Najashi.","Ibn Hisham; Musnad Ahmad 1740")
Q("seerah",2,"In which battle did the archers leave their positions?","Uhud",["Badr","Khandaq","Hunayn"],"At Uhud in 3 AH some archers left the hill, and the Muslims suffered losses.","Quran 3:152; Sahih al-Bukhari 3039")
Q("seerah",2,"Which uncle of the Prophet ﷺ was martyred at Uhud?","Hamzah",["Abbas","Abu Talib","Zubayr"],"Hamzah, 'Sayyid ash-Shuhada', was martyred at Uhud.","Sahih al-Bukhari 4072")
Q("seerah",1,"Which daughter of the Prophet ﷺ married Ali?","Fatimah",["Zaynab","Ruqayyah","Umm Kulthum"],"Fatimah az-Zahra married Ali ibn Abi Talib; she is the leader of the women of Paradise.","Sahih al-Bukhari 3624")
Q("seerah",2,"Which town did the Prophet ﷺ visit for support, where he was stoned?","Ta'if",["Jeddah","Khaybar","Tabuk"],"In Ta'if he ﷺ was rejected and stoned, yet he prayed for their descendants.","Sahih al-Bukhari 3231")
Q("seerah",3,"With whom were the Pledges of Aqabah made?","Believers from Yathrib",["The tribes of Ta'if","The Jews of Khaybar","The Christians of Najran"],"The Ansar of Yathrib pledged at Aqabah, opening the way for the Hijrah.","Ibn Hisham")
Q("seerah",3,"What was the name of the Prophet's camel on the Hijrah?","Al-Qaswa",["Ad-Duldul","Al-Buraq","Ya'fur"],"Al-Qaswa knelt at the site that became Masjid an-Nabawi.","Ibn Hisham; Sahih al-Bukhari 2731")
